def english_note(path, method=""):
    if path.endswith((".early_stopping", ".warmup_early_stopping")):
        return "Stop this stage after 15 validation epochs without improvement and continue with the best saved model; when disabled, use the configured budget."
    if method == "loss_correction" and path == "pipeline.warmup_epochs":
        return "CE training epochs before estimating the transition matrix; select the CE model by noisy-validation loss, then estimate transitions from training and validation predictions."
    if path in COMMON:
        return COMMON[path]
    parts = path.split(".")
    for component in ("optimizer", "scheduler", "model"):
        if component in parts:
            key = component + "." + parts[-1]
            if key in SUFFIXES:
                return SUFFIXES[key]
    for suffix in sorted(SUFFIXES, key=len, reverse=True):
        if path == suffix or path.endswith("." + suffix):
            return SUFFIXES[suffix]
    raise ValueError(f"Missing English parameter explanation: {method}.{path}")
